-- 조건 메서드로 바꾼다

public List<MemberTeamDto> search(MemberSearchCondition cond) {
    return queryFactory
            .select(new QMemberTeamDto(
                    member.id, member.username, member.age,
                    team.id, team.name))
            .from(member)
            .leftJoin(member.team, team)
            .where(usernameEq(cond.getUsername()),
                   teamNameEq(cond.getTeamName()),
                   ageGoe(cond.getAgeGoe()),
                   ageLoe(cond.getAgeLoe()))
            .fetch();
}

private BooleanExpression usernameEq(String username) {
    return hasText(username) ? member.username.eq(username) : null;
}

private BooleanExpression teamNameEq(String teamName) {
    return hasText(teamName) ? team.name.eq(teamName) : null;
}

private BooleanExpression ageGoe(Integer age) {
    return age == null ? null : member.age.goe(age);
}

private BooleanExpression ageLoe(Integer age) {
    return age == null ? null : member.age.loe(age);
}


